   "signature": "const AUTH_DOMAINS = {\n  ACTIVATE: \"PHX-GRAPH-ACT-V1\",\n  FREEZE: \"PHX-GRAPH-FRZ-V2\",\n  REVOKE: \"PHX-OP-REVOKE-V3\",\n} as const",
