   "signature": "const AUTOPILOT_ERRORS = [\n  \"NotALaunch\",\n  \"LaunchNotLive\",\n  \"InvalidCertificate\",\n  \"InvalidDbcConfig\",\n  \"MintAlreadyBound\",\n  \"MintNotBound\",\n  \"InvalidGraph\",\n  \"GraphMismatch\",\n  \"InvalidAuthorization\",\n  \"StaleAuthorization\",\n  \"Frozen\",\n  \"NoActiveGraph\",\n  \"NoPendingUpdate\",\n  \"ActivationInPast\",\n  \"TimelockTooShort\",\n  \"UpdateNotDue\",\n  \"PendingUpdateDue\",\n  \"NoOperator\",\n  \"NoSuchNode\",\n  \"NodeNotDue\",\n  \"NotGraduated\",\n  \"MaxRunsReached\",\n  \"BudgetSpent\",\n  \"ConditionFalse\",\n  \"WrongOperator\",\n  \"AmountNotAllowed\",\n  \"InvalidAmount\",\n  \"NothingToDo\",\n  \"PremiumExceeded\",\n  \"PriceOutOfRange\",\n  \"SwapShortfall\",\n  \"InvalidPool\",\n  \"InvalidDammAccounts\",\n  \"InvalidRecipientAccounts\",\n  \"PriceNotObserved\",\n  \"MathOverflow\",\n  \"UnexpectedAccounts\",\n  \"AmountTooSmall\",\n  \"InvalidDammConfig\",\n  \"PoolAlreadyBound\",\n  \"FreezeExpired\",\n  // Audit round 4: a keeper's partial buyback must leave a swappable remainder (A4-2); a distribution with no\n  // recipient account to pay (M4).\n  \"RemainderTooSmall\",\n  \"NoRecipientAccount\",\n] as const",
